{
  "pipeline": "logs · payment",
  "stage": "processing",
  "processor": {
    "type": "drop",
    "name": "Sift · drop DEBUG logs from payment",
    "matcher": "matchesValue(service.name, \"payment\") and loglevel == \"DEBUG\""
  }
}

{
  "pipeline": "spans · frontend",
  "stage": "processing",
  "processor": {
    "type": "drop",
    "name": "Sift · drop successful /healthz spans",
    "matcher": "matchesValue(service.name, \"frontend\") and http.route == \"/healthz\" and http.response.status_code == 200"
  }
}

{
  "pipeline": "logs · cart",
  "stage": "processing",
  "processor": {
    "type": "drop",
    "name": "Sift · drop re-logged inventory timeouts",
    "matcher": "matchesValue(service.name, \"cart\") and matchesPhrase(content, \"Timeout calling inventory\") and code.function.name != \"InventoryClient.reserve\""
  }
}

{
  "pipeline": "logs · inventory",
  "metricExtraction": {
    "type": "counter",
    "name": "Sift · count inventory heartbeats",
    "metric": "log.inventory.heartbeat.count",
    "dimensions": ["k8s.pod.name"],
    "matcher": "matchesValue(service.name, \"inventory\") and matchesPhrase(content, \"heartbeat ok\")"
  },
  "storage": {
    "type": "noStorage",
    "name": "Sift · do not store heartbeat lines",
    "matcher": "matchesValue(service.name, \"inventory\") and matchesPhrase(content, \"heartbeat ok\")"
  }
}

{
  "pipeline": "logs · email",
  "stage": "processing",
  "processor": {
    "type": "dql",
    "name": "Sift · mask customer email addresses",
    "matcher": "matchesValue(service.name, \"email\") and matchesPhrase(content, \"Sent confirmation to user\")",
    "script": "fieldsAdd content = replacePattern(content, \"[a-zA-Z0-9._%+-]+ '@' [a-zA-Z0-9.-]+\", \"***@***\")"
  }
}

{
  "pipeline": "spans · inventory",
  "stage": "processing",
  "processor": {
    "type": "fieldsRemove",
    "name": "Sift · remove db.statement",
    "matcher": "matchesValue(service.name, \"inventory\") and span.name == \"SELECT inventory.stock\"",
    "fields": ["db.statement"]
  }
}

{
  "pipeline": "spans · frontend",
  "stage": "processing",
  "processor": {
    "type": "drop",
    "name": "Sift · drop static asset spans",
    "matcher": "matchesValue(service.name, \"frontend\") and matchesValue(url.path, \"/static/*\")"
  }
}
